const loadScript = src => new Promise((res, rej) => {
  if (document.querySelector(`script[src="${src}"]`)) {
    res();
    return;
  }
  const s = document.createElement("script");
  s.src = src;
  s.onload = res;
  s.onerror = rej;
  document.head.appendChild(s);
});

