import { useState, useEffect, useRef } from "react";

/* ── Google Fonts fallback for Nikosh (works on Netlify) ── */
const FONT_STYLE = `
  @import url('https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;600;700;800&display=swap');
  @font-face {
    font-family: 'Nikosh';
    src: url('https://fonts.maateen.me/nikosh/Nikosh.woff2') format('woff2'),
         url('https://fonts.maateen.me/nikosh/Nikosh.woff') format('woff'),
         url('https://fonts.maateen.me/nikosh/Nikosh.ttf') format('truetype');
    font-display: swap;
  }
  :root {
    --font: 'Nikosh', 'Hind Siliguri', 'SolaimanLipi', 'Kalpurush', sans-serif;
  }
  * { box-sizing: border-box; margin: 0; padding: 0; }
  body { font-family: var(--font); }
  input, button, th, td, select, textarea { font-family: var(--font) !important; }
  input:focus { outline: 2px solid #1a1a1a; }
  button:active { transform: scale(0.97); }

  /* Mobile responsive table scroll */
  .table-wrap { overflow-x: auto; -webkit-overflow-scrolling: touch; }

  /* Responsive grid for controls */
  .ctrl-bar { display: flex; flex-wrap: wrap; align-items: center; gap: 10px; }

  @media (max-width: 600px) {
    .topbar-title { font-size: 15px !important; }
    .topbar-sub { font-size: 11px !important; }
    .tab-btn { padding: 6px 10px !important; font-size: 12px !important; }
    .report-title-main { font-size: 15px !important; }
    .report-title-sub { font-size: 13px !important; }
    .report-title-date { font-size: 12px !important; }
    .dl-btn { padding: 7px 11px !important; font-size: 12px !important; }
    .sig-block { font-size: 13px !important; }
    .hist-chip { padding: 5px 10px !important; font-size: 12px !important; }
    .save-btn { padding: 7px 14px !important; font-size: 12px !important; }
    .hint-text { font-size: 11px !important; }
    .date-manual-input { font-size: 13px !important; width: 130px !important; }
  }
`;

/* ── Bengali helpers ── */
const BN = ["০","১","২","৩","৪","৫","৬","৭","৮","৯"];
const toBn = (n) => String(n).replace(/[0-9]/g, d => BN[+d]);
const toEn = (s) => String(s).replace(/[০-৯]/g, d => BN.indexOf(d));
const BN_MONTHS = ["জানুয়ারি","ফেব্রুয়ারি","মার্চ","এপ্রিল","মে","জুন","জুলাই","আগস্ট","সেপ্টেম্বর","অক্টোবর","নভেম্বর","ডিসেম্বর"];
const fmtDate = (s) => {
  if (!s) return "";
  const [y,m,d] = s.split("-");
  if (!y || !m || !d) return s;
  return `${toBn(parseInt(d))} ${BN_MONTHS[+m-1]} ${toBn(y)}`;
};
const todayStr = () => new Date().toISOString().split("T")[0];

/* ── Data model ── */
const STATIONS = [
  { id:1, name:"" },
  { id:2, name:"নাসিম ফিলিং স্টেশন, দত্তনগর রোড, জীবননগর, চুয়াডাঙ্গা" },
  { id:3, name:"পিয়াস ফিলিং স্টেশন, দেহাটি জীবননগর, চুয়াডাঙ্গা" },
  { id:4, name:"উৎসব ফিলিং স্টেশন, লক্ষীপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:5, name:"অংগন ফিলিং স্টেশন, সন্তোষপুর জীবননগর, চুয়াডাঙ্গা" },
  { id:6, name:"মেসার্স লিমা ফিলিং স্টেশন, হাসাদাহ জীবননগর" },
];
const FUELS    = ["diesel","petrol","octane"];
const FUEL_LBL = { diesel:"ডিজেল", petrol:"পেট্রোল", octane:"অকটেন" };
const FIELDS   = ["prev","received","closing"];
const FIELD_LBL = { prev:"পূর্বের মজুদ(লিঃ)", received:"ডিপো হতে গ্রহণ (লিঃ)", closing:"সমাপনী মজুদ(লিঃ)" };

const emptyRow  = () => ({ diesel:{prev:"",received:"",closing:""}, petrol:{prev:"",received:"",closing:""}, octane:{prev:"",received:"",closing:""} });
const emptyData = () => STATIONS.map(s => ({ stationId:s.id, ...emptyRow() }));

const STORE_KEY = "fuel_report_v3";
const loadAll   = async () => { try { const r = await window.storage.get(STORE_KEY); return r ? JSON.parse(r.value) : {}; } catch { return {}; } };
const saveAll   = async (d) => { try { await window.storage.set(STORE_KEY, JSON.stringify(d)); } catch(e) { console.error(e); } };

const calcTotal = (rows, fuel, field) => {
  const s = rows.reduce((a,r) => { const n = parseInt(toEn(r[fuel][field])); return a + (isNaN(n) ? 0 : n); }, 0);
  return s > 0 ? toBn(s) : "-";
};

/* ── Load external script ── */
const loadScript = (src) => new Promise((res,rej) => {
  if (document.querySelector(`script[src="${src}"]`)) { res(); return; }
  const s = document.createElement("script"); s.src = src; s.onload = res; s.onerror = rej; document.head.appendChild(s);
});

/* ══════════════════════════════════════
   DOCX generator — Nikosh font embedded
══════════════════════════════════════ */
async function downloadDocx(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/docx/8.5.0/docx.umd.min.js");
  const {
    Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
    AlignmentType, WidthType, BorderStyle, VerticalAlign, PageOrientation
  } = window.docx;

  const bdr     = { style: BorderStyle.SINGLE, size: 4, color: "000000" };
  const borders = { top: bdr, bottom: bdr, left: bdr, right: bdr };
  const FONT    = "Nikosh";

  const mkCell = (text, { rowSpan, colSpan, bold, sz=18, align="center" } = {}) =>
    new TableCell({
      borders, verticalAlign: VerticalAlign.CENTER,
      rowSpan, columnSpan: colSpan,
      margins: { top:60, bottom:60, left:90, right:90 },
      children: [new Paragraph({
        alignment: align === "left" ? AlignmentType.LEFT : AlignmentType.CENTER,
        children: [new TextRun({ text: String(text), font: FONT, size: sz, bold: !!bold })]
      })]
    });

  const totals = {};
  FUELS.forEach(f => { totals[f] = {}; FIELDS.forEach(fi => { totals[f][fi] = calcTotal(rows, f, fi); }); });

  const table = new Table({
    width: { size: 13500, type: WidthType.DXA },
    rows: [
      new TableRow({ children: [
        mkCell("ক্রঃনং",           { rowSpan:2, bold:true, sz:18 }),
        mkCell("উপজেলা",           { rowSpan:2, bold:true, sz:18 }),
        mkCell("প্রতিষ্ঠানের নাম", { rowSpan:2, bold:true, sz:18 }),
        ...FUELS.map(f => mkCell(FUEL_LBL[f], { colSpan:3, bold:true, sz:18 }))
      ]}),
      new TableRow({ children: [
        ...FUELS.flatMap(() => FIELDS.map(fi => mkCell(FIELD_LBL[fi], { sz:15 })))
      ]}),
      ...STATIONS.map((s,i) => new TableRow({ children: [
        mkCell(toBn(String(i+1).padStart(2,"0")), { sz:18 }),
        mkCell(i===0 ? "জীবননগর" : "", { sz:18 }),
        new TableCell({ borders, margins: { top:60, bottom:60, left:90, right:90 },
          children: [new Paragraph({ alignment: AlignmentType.LEFT,
            children: [new TextRun({ text: s.name, font: FONT, size: 16 })] })]
        }),
        ...FUELS.flatMap(f => FIELDS.map(fi => mkCell(rows[i][f][fi] || "-", { sz:18 })))
      ]})),
      new TableRow({ children: [
        new TableCell({ borders, columnSpan:3,
          margins: { top:60, bottom:60, left:90, right:90 },
          children: [new Paragraph({ alignment: AlignmentType.CENTER,
            children: [new TextRun({ text: "সর্বমোট", font: FONT, size: 18, bold: true })] })]
        }),
        ...FUELS.flatMap(f => FIELDS.map(fi => mkCell(totals[f][fi], { bold:true, sz:18 })))
      ]})
    ]
  });

  const run  = (text, sz=22, bold=false) => new TextRun({ text, font: FONT, size: sz, bold });
  const para = (children, align=AlignmentType.CENTER, spacingBefore=0, spacingAfter=0) =>
    new Paragraph({ alignment: align, spacing: { before: spacingBefore, after: spacingAfter }, children });

  const doc = new Document({
    sections: [{ properties: { page: {
      size: { width:15120, height:12240, orientation: PageOrientation.LANDSCAPE },
      margin: { top:720, right:720, bottom:720, left:720 }
    }},
    children: [
      para([run("উপজেলা: জীবননগর", 28, true)],           AlignmentType.CENTER, 0,  80),
      para([run("জ্বালানী তেলের দৈনিক রিপোর্ট", 26, true)], AlignmentType.CENTER, 0,  80),
      para([run(`তারিখ: ${fmtDate(dateStr)}`, 22)],        AlignmentType.CENTER, 0, 200),
      table,
      para([run("স্বাক্ষরিত", 20)],                          AlignmentType.RIGHT, 600, 60),
      para([run("উপজেলা নির্বাহী অফিসার", 20)],             AlignmentType.RIGHT, 0,   60),
      para([run("জীবননগর, চুয়াডাঙ্গা।", 20)],              AlignmentType.RIGHT),
    ]}]
  });

  const blob = await Packer.toBlob(doc);
  const url  = URL.createObjectURL(blob);
  const a    = document.createElement("a");
  a.href     = url;
  a.download = `fuel_report_${dateStr}.docx`;
  document.body.appendChild(a); a.click(); document.body.removeChild(a);
  URL.revokeObjectURL(url);
}

/* ══════════════════════════════════════
   PDF generator — html2canvas + jsPDF
══════════════════════════════════════ */
async function downloadPdf(dateStr, rows) {
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js");
  await loadScript("https://cdnjs.cloudflare.com/ajax/libs/html2canvas/1.4.1/html2canvas.min.js");

  const { jsPDF } = window.jspdf;
  const totals = {};
  FUELS.forEach(f => { totals[f] = {}; FIELDS.forEach(fi => { totals[f][fi] = calcTotal(rows, f, fi); }); });

  const wrapper = document.createElement("div");
  wrapper.style.cssText = "position:fixed;left:-9999px;top:0;width:1120px;background:#fff;padding:28px 32px;color:#000;";

  // inject font into the hidden wrapper
  const styleEl = document.createElement("style");
  styleEl.textContent = `
    @import url('https://fonts.googleapis.com/css2?family=Hind+Siliguri:wght@400;600;700;800&display=swap');
    @font-face {
      font-family: 'Nikosh';
      src: url('https://fonts.maateen.me/nikosh/Nikosh.woff2') format('woff2'),
           url('https://fonts.maateen.me/nikosh/Nikosh.woff') format('woff'),
           url('https://fonts.maateen.me/nikosh/Nikosh.ttf') format('truetype');
    }
    * { font-family: 'Nikosh', 'Hind Siliguri', sans-serif !important; }
  `;
  wrapper.appendChild(styleEl);

  const content = document.createElement("div");
  content.innerHTML = `
    <div style="text-align:center;margin-bottom:8px">
      <div style="font-size:20px;font-weight:800">উপজেলা: জীবননগর</div>
      <div style="font-size:17px;font-weight:700;margin-top:5px">জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div style="font-size:15px;margin-top:5px">তারিখ: ${fmtDate(dateStr)}</div>
    </div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-top:12px">
      <thead>
        <tr>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;font-weight:700;text-align:center">ক্রঃনং</th>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;font-weight:700;text-align:center">উপজেলা</th>
          <th rowspan="2" style="border:1px solid #000;padding:6px 4px;font-weight:700;text-align:center;min-width:160px">প্রতিষ্ঠানের নাম</th>
          ${FUELS.map(f=>`<th colspan="3" style="border:1px solid #000;padding:6px 4px;font-weight:700;text-align:center">${FUEL_LBL[f]}</th>`).join("")}
        </tr>
        <tr>
          ${FUELS.map(()=>FIELDS.map(fi=>`<th style="border:1px solid #000;padding:5px 3px;font-size:10px;text-align:center">${FIELD_LBL[fi]}</th>`).join("")).join("")}
        </tr>
      </thead>
      <tbody>
        ${STATIONS.map((s,i)=>`
          <tr>
            <td style="border:1px solid #000;padding:5px 4px;text-align:center">${toBn(String(i+1).padStart(2,"0"))}</td>
            <td style="border:1px solid #000;padding:5px 4px;text-align:center">${i===0?"জীবননগর":""}</td>
            <td style="border:1px solid #000;padding:5px 4px;font-size:11px">${s.name}</td>
            ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:5px 4px;text-align:center">${rows[i][f][fi]||"-"}</td>`).join("")).join("")}
          </tr>
        `).join("")}
        <tr>
          <td colspan="3" style="border:1px solid #000;padding:6px 4px;text-align:center;font-weight:800">সর্বমোট</td>
          ${FUELS.map(f=>FIELDS.map(fi=>`<td style="border:1px solid #000;padding:5px 4px;text-align:center;font-weight:700">${totals[f][fi]}</td>`).join("")).join("")}
        </tr>
      </tbody>
    </table>
    <div style="text-align:right;margin-top:50px;padding-right:20px;font-size:14px;line-height:1.9">
      স্বাক্ষরিত<br/>উপজেলা নির্বাহী অফিসার<br/>জীবননগর, চুয়াডাঙ্গা।
    </div>
  `;
  wrapper.appendChild(content);
  document.body.appendChild(wrapper);

  if (document.fonts && document.fonts.ready) await document.fonts.ready;
  await new Promise(r => setTimeout(r, 500));

  const canvas  = await window.html2canvas(wrapper, { scale:2, useCORS:true, backgroundColor:"#ffffff" });
  document.body.removeChild(wrapper);

  const imgData = canvas.toDataURL("image/png");
  const pdf     = new jsPDF({ orientation:"landscape", unit:"mm", format:"a4" });
  const pW      = pdf.internal.pageSize.getWidth();
  const pH      = pdf.internal.pageSize.getHeight();
  const finalW  = pW - 10;
  const finalH  = (canvas.height / canvas.width) * finalW;
  pdf.addImage(imgData, "PNG", 5, 5, finalW, Math.min(finalH, pH-10));
  pdf.save(`fuel_report_${dateStr}.pdf`);
}

/* ══════════════════════════
   Main App
══════════════════════════ */
export default function App() {
  const [view, setView]         = useState("entry");
  const [allData, setAllData]   = useState({});
  const [selDate, setSelDate]   = useState(todayStr());
  const [manualDate, setManual] = useState(todayStr()); // manual text input
  const [rows, setRows]         = useState(emptyData());
  const [loaded, setLoaded]     = useState(false);
  const [savedDates, setSaved]  = useState([]);
  const [histDate, setHistDate] = useState("");
  const [histRows, setHistRows] = useState(null);
  const [histEdit, setHistEdit] = useState(false); // history edit mode
  const [histRowsEdit, setHistRowsEdit] = useState(null);
  const [histNewDate, setHistNewDate]     = useState("");
  const [histNewManual, setHistNewManual] = useState("");
  const [histNewRows, setHistNewRows]     = useState(null);
  const [histMode, setHistMode]           = useState("list"); // "list" | "new"
  const [msg, setMsg]           = useState("");
  const [dlState, setDlState]   = useState("");

  useEffect(() => {
    loadAll().then(all => {
      setAllData(all);
      setSaved(Object.keys(all).sort().reverse());
      setLoaded(true);
    });
  }, []);

  // When selDate changes, load existing or auto-fill prev closing → current prev
  useEffect(() => {
    if (!loaded) return;
    setManual(selDate);
    if (allData[selDate]) { setRows(allData[selDate]); return; }
    const prev = Object.keys(allData).filter(d => d < selDate).sort().reverse()[0];
    if (prev) {
      setRows(allData[prev].map(r => ({
        stationId: r.stationId,
        diesel: { prev: r.diesel.closing, received: "", closing: "" },
        petrol: { prev: r.petrol.closing, received: "", closing: "" },
        octane: { prev: r.octane.closing, received: "", closing: "" },
      })));
    } else { setRows(emptyData()); }
  }, [selDate, loaded]);

  const applyManualDate = (val) => {
    // Accept YYYY-MM-DD
    if (/^\d{4}-\d{2}-\d{2}$/.test(val)) {
      setSelDate(val);
    }
  };

  const setCell = (ri, f, fi, v) =>
    setRows(rs => rs.map((r, i) => i !== ri ? r : { ...r, [f]: { ...r[f], [fi]: v } }));

  const setHistCell = (ri, f, fi, v) =>
    setHistRowsEdit(rs => rs.map((r, i) => i !== ri ? r : { ...r, [f]: { ...r[f], [fi]: v } }));

  const flash = (m) => { setMsg(m); setTimeout(() => setMsg(""), 2500); };

  const handleSave = async () => {
    const updated = { ...allData, [selDate]: rows };
    setAllData(updated); setSaved(Object.keys(updated).sort().reverse());
    await saveAll(updated); flash("✓ সংরক্ষিত হয়েছে!");
  };

  const handleHistSave = async () => {
    const updated = { ...allData, [histDate]: histRowsEdit };
    setAllData(updated); setSaved(Object.keys(updated).sort().reverse());
    setHistRows(histRowsEdit);
    await saveAll(updated);
    setHistEdit(false);
    flash("✓ সম্পাদিত তথ্য সংরক্ষিত!");
  };

  // Build rows for a given date: existing data or auto-fill from previous day closing
  const getRowsForDate = (date, currentAllData) => {
    if (currentAllData[date]) return JSON.parse(JSON.stringify(currentAllData[date]));
    const prev = Object.keys(currentAllData).filter(d => d < date).sort().reverse()[0];
    if (prev) {
      return currentAllData[prev].map(r => ({
        stationId: r.stationId,
        diesel: { prev: r.diesel.closing, received: "", closing: "" },
        petrol: { prev: r.petrol.closing, received: "", closing: "" },
        octane: { prev: r.octane.closing, received: "", closing: "" },
      }));
    }
    return emptyData();
  };

  const applyHistNewDate = (date, currentAllData) => {
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return;
    setHistNewDate(date);
    setHistNewManual(date);
    setHistNewRows(getRowsForDate(date, currentAllData));
  };

  const setHistNewCell = (ri, f, fi, v) =>
    setHistNewRows(rs => rs.map((r, i) => i !== ri ? r : { ...r, [f]: { ...r[f], [fi]: v } }));

  const handleHistNewSave = async () => {
    if (!histNewDate || !histNewRows) return;
    const updated = { ...allData, [histNewDate]: histNewRows };
    setAllData(updated); setSaved(Object.keys(updated).sort().reverse());
    await saveAll(updated);
    flash("✓ সংরক্ষিত হয়েছে!");
    // switch back to list and select the new date
    setHistMode("list");
    setHistDate(histNewDate);
    setHistRows(histNewRows);
    setHistEdit(false);
  };

  const handleDl = async (type, date, rowsArr) => {
    const key = date + "_" + type; setDlState(key);
    try {
      if (type === "docx") await downloadDocx(date, rowsArr);
      else                 await downloadPdf(date, rowsArr);
    } catch(e) { console.error(e); alert("ডাউনলোড ব্যর্থ: " + e.message); }
    setDlState("");
  };

  const deleteDate = async (d) => {
    if (!window.confirm("এই তারিখের তথ্য মুছে ফেলবেন?")) return;
    const u = { ...allData }; delete u[d];
    setAllData(u); setSaved(Object.keys(u).sort().reverse());
    await saveAll(u);
    if (histDate === d) { setHistDate(""); setHistRows(null); setHistEdit(false); }
  };

  /* ── Styles ── */
  const TH_HD  = { border:"1px solid #000", padding:"5px 6px", fontWeight:700, textAlign:"center", fontSize:12, color:"#000", background:"#fff", whiteSpace:"nowrap" };
  const TH_SUB = { ...TH_HD, fontSize:10, fontWeight:600 };
  const TD     = { border:"1px solid #000", padding:"3px 4px", verticalAlign:"middle", color:"#000", fontSize:12 };

  /* ── Download bar ── */
  const DlBar = ({ date, rowsArr }) => (
    <div style={{ display:"flex", gap:8, flexWrap:"wrap", marginTop:14 }}>
      {[["docx","📄 DOCX"], ["pdf","📕 PDF"]].map(([t, lbl]) => {
        const busy = dlState === date + "_" + t;
        return (
          <button key={t} className="dl-btn" onClick={() => handleDl(t, date, rowsArr)} disabled={!!dlState}
            style={{ background: busy ? "#888" : "#1a1a1a", color:"#fff", border:"none", borderRadius:5, padding:"8px 16px", cursor: busy ? "not-allowed" : "pointer", fontWeight:700, fontSize:13 }}>
            {busy ? "⏳ তৈরি হচ্ছে..." : lbl + " ডাউনলোড"}
          </button>
        );
      })}
    </div>
  );

  /* ── Report table ── */
  const ReportTable = ({ rowsArr, editable, setCellFn }) => (
    <div className="table-wrap">
      <table style={{ borderCollapse:"collapse", width:"100%", minWidth:820, background:"#fff", border:"1px solid #000" }}>
        <thead>
          <tr>
            <th rowSpan={2} style={TH_HD}>ক্রঃনং</th>
            <th rowSpan={2} style={TH_HD}>উপজেলা</th>
            <th rowSpan={2} style={{ ...TH_HD, minWidth:160 }}>প্রতিষ্ঠানের নাম</th>
            {FUELS.map(f => <th key={f} colSpan={3} style={TH_HD}>{FUEL_LBL[f]}</th>)}
          </tr>
          <tr>
            {FUELS.map(f => FIELDS.map((fi, hi) => (
              <th key={f+hi} style={TH_SUB}>{FIELD_LBL[fi]}</th>
            )))}
          </tr>
        </thead>
        <tbody>
          {STATIONS.map((s, i) => (
            <tr key={s.id} style={{ background:"#fff" }}>
              <td style={{ ...TD, textAlign:"center", fontWeight:600 }}>{toBn(String(i+1).padStart(2,"0"))}</td>
              <td style={{ ...TD, textAlign:"center" }}>{i===0 ? "জীবননগর" : ""}</td>
              <td style={{ ...TD, fontSize:11 }}>{s.name}</td>
              {FUELS.map(f => FIELDS.map(fi => (
                <td key={f+fi} style={{ ...TD, padding: editable ? 2 : 4 }}>
                  {fi === "prev" ? (
                    <div style={{ textAlign:"center", padding:"3px 6px", background:"#f0f0f0", borderRadius:3, color:"#000", fontWeight:600, fontSize:12 }}>
                      {rowsArr[i][f][fi] || <span style={{ color:"#aaa" }}>-</span>}
                    </div>
                  ) : editable ? (
                    <input
                      value={rowsArr[i][f][fi]}
                      onChange={e => setCellFn(i, f, fi, e.target.value)}
                      style={{ width:"100%", minWidth:60, border: fi==="closing" ? "2px solid #000" : "1px solid #999", borderRadius:3, padding:"4px 5px", textAlign:"center", fontSize:12, background:"#fff", boxSizing:"border-box", color:"#000" }}
                      placeholder="-"
                    />
                  ) : (
                    <div style={{ textAlign:"center", fontSize:12 }}>{rowsArr[i][f][fi] || "-"}</div>
                  )}
                </td>
              )))}
            </tr>
          ))}
          <tr style={{ background:"#fff" }}>
            <td colSpan={3} style={{ ...TD, fontWeight:800, textAlign:"center" }}>সর্বমোট</td>
            {FUELS.map(f => FIELDS.map(fi => (
              <td key={f+fi} style={{ ...TD, fontWeight:700, textAlign:"center" }}>
                {calcTotal(rowsArr, f, fi)}
              </td>
            )))}
          </tr>
        </tbody>
      </table>
    </div>
  );

  const Signature = () => (
    <div className="sig-block" style={{ textAlign:"right", marginTop:20, paddingRight:12, color:"#000", fontSize:14, lineHeight:"2" }} spellCheck={false}>
      <div spellCheck={false}>স্বাক্ষরিত</div>
      <div spellCheck={false}>উপজেলা নির্বাহী অফিসার</div>
      <div spellCheck={false}>জীবননগর, চুয়াডাঙ্গা।</div>
    </div>
  );

  const ReportTitle = ({ date }) => (
    <div style={{ textAlign:"center", background:"#fff", padding:"12px 10px 8px", marginBottom:10, borderBottom:"2px solid #000" }}>
      <div className="report-title-main" style={{ fontWeight:800, fontSize:17, color:"#000" }}>উপজেলা: জীবননগর</div>
      <div className="report-title-sub" style={{ fontWeight:700, fontSize:15, marginTop:3, color:"#000" }}>জ্বালানী তেলের দৈনিক রিপোর্ট</div>
      <div className="report-title-date" style={{ marginTop:4, fontSize:13, color:"#000" }}>তারিখ: {fmtDate(date)}</div>
    </div>
  );

  if (!loaded) return (
    <div style={{ padding:40, textAlign:"center", fontFamily:"var(--font)", fontSize:18 }}>
      লোড হচ্ছে...
    </div>
  );

  return (
    <div spellCheck={false} style={{ fontFamily:"var(--font)", minHeight:"100vh", background:"#f2f2f2", color:"#000" }}>
      <style>{FONT_STYLE + `
        * { -webkit-spell-check: none; }
        [spellcheck="false"] { text-decoration: none !important; }
      `}</style>

      {/* ── Topbar ── */}
      <div style={{ background:"#1a1a1a", color:"#fff", padding:"12px 16px", display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:8 }}>
        <div>
          <div className="topbar-title" style={{ fontWeight:800, fontSize:17 }}>⛽ জ্বালানী তেলের দৈনিক রিপোর্ট</div>
          <div className="topbar-sub" style={{ fontSize:12, opacity:.7 }}>উপজেলা: জীবননগর, চুয়াডাঙ্গা</div>
        </div>
        <div style={{ display:"flex", gap:6 }}>
          {[["entry","📝 তথ্য প্রবেশ"],["history","📅 তারিখ ভিত্তিক"]].map(([v,l]) => (
            <button key={v} className="tab-btn" onClick={() => setView(v)}
              style={{ background: view===v ? "#fff" : "transparent", color: view===v ? "#1a1a1a" : "#fff", border: view===v ? "none" : "1px solid rgba(255,255,255,.45)", borderRadius:5, padding:"7px 13px", cursor:"pointer", fontWeight:700, fontSize:13 }}>
              {l}
