              onKeyDown={e => { if (e.key === "Enter") applyManualDate(manualDate); }}
              placeholder="YYYY-MM-DD"
              style={{ padding:"7px 9px", border:"1px solid #999", fontSize:13, borderRadius:4, width:130, color:"#000" }}
            />

            <div style={{ fontWeight:600, fontSize:13, color:"#333" }}>{fmtDate(selDate)}</div>

            <button className="save-btn" onClick={handleSave}
              style={{ background:"#1a1a1a", color:"#fff", border:"none", padding:"8px 18px", fontSize:13, cursor:"pointer", fontWeight:700, borderRadius:4 }}>
              💾 সংরক্ষণ
            </button>
            {msg && <span style={{ color:"#000", fontWeight:700, fontSize:13, border:"1px solid #000", padding:"3px 10px", borderRadius:3 }}>{msg}</span>}
          </div>

          <ReportTitle date={selDate} />
          <ReportTable rowsArr={rows} editable={true} setCellFn={setCell} />
          <Signature />
          <DlBar date={selDate} rowsArr={allData[selDate] || rows} />

          <div className="hint-text" style={{ marginTop:10, fontSize:12, color:"#666" }}>
            💡 <b>পূর্বের মজুদ</b> আগের দিনের সমাপনী মজুদ থেকে স্বয়ংক্রিয়ভাবে আসে। &nbsp;<b>গাঢ় বর্ডার</b> = সমাপনী মজুদ।
          </div>
        </div>
      )}

      {/* ── History view ── */}
      {view === "history" && (
        <div style={{ padding:"16px 12px" }}>

          {/* Header + New Entry button */}
          <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", flexWrap:"wrap", gap:8, borderBottom:"2px solid #000", paddingBottom:8, marginBottom:12 }}>
            <div style={{ fontWeight:700, fontSize:15, color:"#000" }}>📅 সংরক্ষিত তারিখসমূহ</div>
            <button
              onClick={() => {
                setHistMode("new");
                const nd = todayStr();
                setHistNewDate(nd);
                setHistNewManual(nd);
                setHistNewRows(getRowsForDate(nd, allData));
              }}
              style={{ background:"#1a1a1a", color:"#fff", border:"none", padding:"7px 16px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
              ➕ নতুন তারিখ এন্ট্রি
            </button>
          </div>

          {/* ── NEW ENTRY MODE ── */}
          {histMode === "new" && (
            <div style={{ background:"#fff", border:"1px solid #ccc", borderRadius:6, padding:"14px 12px", marginBottom:16 }}>
              <div className="ctrl-bar" style={{ marginBottom:12 }}>
                <label style={{ fontWeight:700, fontSize:14 }}>📅 তারিখ:</label>
                <input type="date" value={histNewDate}
                  onChange={e => applyHistNewDate(e.target.value, allData)}
                  style={{ padding:"7px 10px", border:"1px solid #999", fontSize:14, borderRadius:4 }}
                />
                <input type="text" className="date-manual-input"
                  value={histNewManual}
                  onChange={e => setHistNewManual(e.target.value)}
                  onBlur={e => applyHistNewDate(e.target.value, allData)}
                  onKeyDown={e => { if (e.key==="Enter") applyHistNewDate(histNewManual, allData); }}
                  placeholder="YYYY-MM-DD"
                  style={{ padding:"7px 9px", border:"1px solid #999", fontSize:13, borderRadius:4, width:130 }}
                />
                <div style={{ fontWeight:600, fontSize:13, color:"#333" }}>{fmtDate(histNewDate)}</div>
              </div>

              {histNewRows && (
                <>
                  <ReportTitle date={histNewDate} />
                  <ReportTable rowsArr={histNewRows} editable={true} setCellFn={setHistNewCell} />
                  <Signature />
                  <div style={{ display:"flex", gap:8, marginTop:12, flexWrap:"wrap" }}>
                    <button onClick={handleHistNewSave}
                      style={{ background:"#1a1a1a", color:"#fff", border:"none", padding:"8px 18px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
                      💾 সংরক্ষণ
                    </button>
                    <button onClick={() => setHistMode("list")}
                      style={{ background:"#fff", color:"#1a1a1a", border:"1px solid #1a1a1a", padding:"8px 16px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
                      ✕ বাতিল
                    </button>
                    {msg && <span style={{ color:"#000", fontWeight:700, fontSize:13, border:"1px solid #000", padding:"3px 10px", borderRadius:3 }}>{msg}</span>}
                  </div>
                  <div className="hint-text" style={{ marginTop:8, fontSize:12, color:"#666" }}>
                    💡 <b>পূর্বের মজুদ</b> আগের দিনের সমাপনী মজুদ থেকে স্বয়ংক্রিয়ভাবে আসে।
                  </div>
                </>
              )}
            </div>
          )}

          {/* ── DATE CHIPS LIST ── */}
          {savedDates.length === 0 && <div style={{ color:"#666", padding:"12px 0" }}>কোনো তথ্য সংরক্ষিত নেই।</div>}

          <div style={{ display:"flex", flexWrap:"wrap", gap:7, marginBottom:16 }}>
            {savedDates.map(d => (
              <div key={d}
                onClick={() => {
                  setHistDate(d);
                  setHistRows(allData[d]);
                  setHistEdit(false);
                  setHistRowsEdit(null);
                  setHistMode("list");
                }}
                className="hist-chip"
                style={{ background: histDate===d && histMode==="list" ? "#1a1a1a" : "#fff", color: histDate===d && histMode==="list" ? "#fff" : "#000", border:"1px solid #1a1a1a", padding:"6px 12px", cursor:"pointer", display:"flex", alignItems:"center", gap:7, fontWeight:600, fontSize:13, borderRadius:4 }}>
                {fmtDate(d)}
                <span
                  onClick={e => { e.stopPropagation(); deleteDate(d); }}
                  style={{ color: histDate===d && histMode==="list" ? "#fff" : "#c00", fontWeight:900, fontSize:16, cursor:"pointer", lineHeight:1 }}>
                  ×
                </span>
              </div>
            ))}
          </div>

          {/* ── SELECTED DATE VIEW / EDIT ── */}
          {histRows && histMode === "list" && (
            <div>
              {/* Date change bar */}
              <div className="ctrl-bar" style={{ background:"#fff", border:"1px solid #ccc", borderRadius:4, padding:"10px 12px", marginBottom:12 }}>
                <label style={{ fontWeight:700, fontSize:14 }}>📅 তারিখ পরিবর্তন:</label>
                <input type="date" value={histDate}
                  onChange={e => {
                    const nd = e.target.value;
                    if (!nd) return;
                    // rename: remove old key, add new
                    const updated = { ...allData };
                    const rowsData = histEdit ? histRowsEdit : histRows;
                    delete updated[histDate];
                    updated[nd] = rowsData;
                    setAllData(updated);
                    setSaved(Object.keys(updated).sort().reverse());
                    saveAll(updated);
                    setHistDate(nd);
                    setHistRows(rowsData);
                    if (histEdit) setHistRowsEdit(rowsData);
                    flash("✓ তারিখ পরিবর্তিত হয়েছে!");
                  }}
                  style={{ padding:"7px 10px", border:"1px solid #999", fontSize:14, borderRadius:4 }}
                />
                <div style={{ fontWeight:600, fontSize:13, color:"#333" }}>{fmtDate(histDate)}</div>
                {msg && <span style={{ color:"#000", fontWeight:700, fontSize:13, border:"1px solid #000", padding:"3px 10px", borderRadius:3 }}>{msg}</span>}
              </div>

              <ReportTitle date={histDate} />

              {histEdit ? (
                <>
                  <ReportTable rowsArr={histRowsEdit} editable={true} setCellFn={setHistCell} />
                  <div style={{ display:"flex", gap:8, marginTop:12, flexWrap:"wrap" }}>
                    <button onClick={handleHistSave}
                      style={{ background:"#1a1a1a", color:"#fff", border:"none", padding:"8px 18px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
                      💾 পরিবর্তন সংরক্ষণ
                    </button>
                    <button onClick={() => { setHistEdit(false); setHistRowsEdit(null); }}
                      style={{ background:"#fff", color:"#1a1a1a", border:"1px solid #1a1a1a", padding:"8px 16px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
                      ✕ বাতিল
                    </button>
                    {msg && <span style={{ color:"#000", fontWeight:700, fontSize:13, border:"1px solid #000", padding:"3px 10px", borderRadius:3 }}>{msg}</span>}
                  </div>
                </>
              ) : (
                <>
                  <ReportTable rowsArr={histRows} editable={false} setCellFn={() => {}} />
                  <div style={{ display:"flex", gap:8, marginTop:12, flexWrap:"wrap", alignItems:"center" }}>
                    <button onClick={() => { setHistEdit(true); setHistRowsEdit(JSON.parse(JSON.stringify(histRows))); }}
                      style={{ background:"#fff", color:"#1a1a1a", border:"1px solid #1a1a1a", padding:"7px 16px", cursor:"pointer", fontWeight:700, fontSize:13, borderRadius:4 }}>
                      ✏️ সম্পাদনা করুন
                    </button>
                  </div>
                </>
              )}

              <Signature />
              <DlBar date={histDate} rowsArr={histEdit ? histRowsEdit : histRows} />
            </div>
          )}
        </div>
      )}
    </div>
  );
}
